def try_rotate_cluster(target_orientation):
    """Try ACTION5 and ACTION7 to rotate the cluster to target_orientation.

    Returns the action number that worked, or None if neither worked.
    """
    for a in [5, 7]:
        try:
            r = action(a)
            if r.get('n_changed', 0) > 0:
                if get_cluster_orientation() == target_orientation:
                    return a
                # If it changed but not to target, revert if possible? 
                # For now, just return the action that changed something.
                # The player should check state next turn.
                return a
        except Exception:
            pass
    return None
